"""Generates docs/MOD_FILES.md from the lockfiles, so the page cannot drift from what the
installer checks. Run `capture mods docs` after changing a lockfile."""
import os

from .. import paths
from . import INSTALLERS, installer
from .sources import SHARED_LOCK, load_locks

PAGE = os.path.join(paths.REPO, "docs", "MOD_FILES.md")

INTRO = """# Mod files

<!-- Generated by `capture mods docs` from the lockfiles. Edit those, not this page. -->

`capture install <game>` needs these third-party files. None of them is in this repository.
Put what you have in `out/mods/` (or pass `--mods <folder, archive or bundle>`): archives can
stay exactly as downloaded, files are recognised by their SHA-256, not by name or folder.

- **Download**: `capture mods fetch <game>` downloads these and checks their hashes.
- **Supply yourself**: may not be redistributed, so get them from the page given.
- `capture mods status <game>` shows what was found on this machine and what is missing.
- To set up another of your own machines without downloading again, make a bundle on a machine
  that has everything: `capture mods bundle <game> -o mods.zip --with-supplied`, then
  `capture install <game> --mods mods.zip` there. Keep such a bundle off the internet and out of
  git: it holds files that may not be redistributed.

The lockfiles pin the versions this repository was tested with:
`capture/install/mods.lock.json` (every game) and `adapters/<game>/mods.lock.json`.
"""


def _mod(mod_id, m):
    how = {"download": "Download", "supplied": "Supply yourself"}.get(m.get("source"), m.get("source", ""))
    lines = ["### %s" % m["title"], "",
             "%s%s" % ("**Required.** " if m.get("required") else "**Optional.** ", m.get("what", "")), "",
             "| | |", "|---|---|",
             "| How to get it | **%s**: %s |" % (how, m.get("page", ""))]
    a = m.get("archive")
    if a:
        lines.append("| File as downloaded | `%s`, %s bytes%s |" % (
            a["name"], "{:,}".format(a["size"]), ", SHA-256 `%s`" % a["sha256"] if a.get("sha256") else ""))
        if a.get("url"):
            lines.append("| Direct link | %s |" % a["url"])
    lines.append("| Licence | %s (%s) |" % (m.get("licence", "?"), "may be redistributed" if m.get("redistributable")
                                           else "may NOT be redistributed"))
    if m.get("note"):
        lines.append("| Note | %s |" % m["note"])
    lines.append("| Lockfile | `%s`, id `%s` |" % (m["lock"], mod_id))
    if m.get("files"):
        lines += ["", "| File used | Size | SHA-256 |", "|---|---|---|"]
        for f in m["files"]:
            lines.append("| %s%s | %s | %s |" % (
                "[`%s`](%s)" % (f["name"], f["url"]) if f.get("url") else "`%s`" % f["name"],
                " (optional: `%s`)" % f["option"] if f.get("option") else "",
                "{:,}".format(f["size"]) if f.get("size") else "any", "`%s`" % f["sha256"] if f.get("sha256") else "any version, matched by name"))
    else:
        lines += ["", "Its files are not pinned yet."]
    return "\n".join(lines) + "\n"


def generate():
    shared = load_locks(SHARED_LOCK)
    parts = [INTRO, "## Every game\n"]
    parts += [_mod(k, m) for k, m in shared.items()]
    for game in sorted(INSTALLERS):
        mod = installer(game)
        parts.append("## %s\n" % mod.TITLE)
        parts += [_mod(k, m) for k, m in load_locks(mod.LOCK).items()]
    text = "\n".join(parts)
    os.makedirs(os.path.dirname(PAGE), exist_ok=True)
    with open(PAGE, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    return PAGE
